📊 3. Dynamic Views: Reusing LC-MD's `NotesHub` & Query Tables

LC-MD's `NotesHub` already supports dynamic multi-column filtering, tag tallies, and grid card views. In **Anymd**, this becomes our **Dynamic Schema Presentation Layer**:

```typescript
export interface AnymdQueryFilter {
  tag?: string;
  type?: string;
  searchQuery?: string;
  sortField?: string;
  sortOrder?: 'asc' | 'desc';
}

export class AnymdDatabaseQueryEngine {
  private documents: Map<string, IngestedMarkdownDoc> = new Map();
  private sidecars: Map<string, AnymdSidecar> = new Map();

  public insert(doc: IngestedMarkdownDoc, sidecar: AnymdSidecar) {
    this.documents.set(doc.uid, doc);
    this.sidecars.set(doc.uid, sidecar);
  }

  public query(filter: AnymdQueryFilter) {
    let results = Array.from(this.documents.values()).map(doc => {
      const sidecar = this.sidecars.get(doc.uid);
      return {
        ...doc,
        sidecar
      };
    });

    if (filter.tag) {
      results = results.filter(r => r.tags.includes(filter.tag!));
    }

    if (filter.searchQuery) {
      const q = filter.searchQuery.toLowerCase();
      results = results.filter(r => r.cleanBody.toLowerCase().includes(q) || r.filename.toLowerCase().includes(q));
    }

    return results;
  }

  // Live Table Generator
  public renderTableView(schemaFields: string[]) {
    return Array.from(this.documents.values()).map(doc => {
      const sidecar = this.sidecars.get(doc.uid);
      const row: Record<string, any> = {
        title: doc.filename.replace(/\.md$/, ''),
        wordCount: doc.wordCount,
        readingTime: `${sidecar?.computed.readingTimeMinutes || 1} min`,
        tags: doc.tags.join(', ')
      };

      schemaFields.forEach(f => {
        row[f] = doc.frontmatter[f] || sidecar?.userProperties[f] || '—';
      });

      return row;
    });
  }
}
```

