export interface AnymdSchema {
  id: string;
  name: string;
  match: {
    tags?: string[];
    frontmatterType?: string;
  };
  fields: Record<string, {
    type: 'string' | 'number' | 'boolean' | 'datetime' | 'enum';
    default?: any;
  }>;
