export class AnymdSchemaRegistry {
  private schemas: Map<string, AnymdSchema> = new Map();

  public register(schema: AnymdSchema) {
    this.schemas.set(schema.id, schema);
  }

  public resolve(doc: AnymdDocument): AnymdSchema | null {
    for (const schema of this.schemas.values()) {
      if (schema.match.frontmatterType && doc.frontmatter.type === schema.match.frontmatterType) {
        return schema;
      }
      if (schema.match.tags && schema.match.tags.some(t => doc.tags.includes(t.toLowerCase()))) {
        return schema;
      }
    }
    return null;
  }
}
