export interface SerialShardRule {
  format: 'zettel_timestamp' | 'hash_bucket' | 'luhn_decimal';
  maxFilesPerDir: number;
}

export class AnymdZettelSerializer {
  /**
   * Translates a flat logical Zettel ID into a sharded physical disk path
   * Example: '202608191530_distributed_systems.md' -> '2026/08/19/202608191530_distributed_systems.md'
   */
  public static computePhysicalPath(filename: string, strategy: string = 'chrono_shard'): string {
    const uidMatch = filename.match(/^(\d{4})(\d{2})(\d{2})(\d{4})?/);

    if (strategy === 'chrono_shard' && uidMatch) {
      const [_, year, month, day] = uidMatch;
      return `${year}/${month}/${day}/${filename}`;
    }

    if (strategy === 'hash_bucket') {
      // Fast 2-char hex bucket (shards/7f/filename.md)
      const bucket = filename.slice(0, 2).toLowerCase();
      return `shards/${bucket}/${filename}`;
    }

    // Default: Root flat folder
    return filename;
  }

  /**
   * Resolves any [[WikiLink]] or UID target across all physical shards in O(1) time
   */
  public static resolveVirtualLink(linkTarget: string, physicalIndexMap: Map<string, string>): string | null {
    // Strips folder paths if present in link, matching against pure filename UID
    const cleanTarget = linkTarget.replace(/^.*[\\\/]/, '').replace(/\.md$/, '');
