  // Blazing fast 32-bit non-cryptographic FNV-1a hash (sub-microsecond)
  private static fastFnv1a(str: string): string {
    let hash = 0x811c9dc5;
    for (let i = 0; i < str.length; i++) {
      hash ^= str.charCodeAt(i);
      hash += (hash << 1) + (hash << 4) + (hash << 7) + (hash << 8) + (hash << 24);
    }
    return (hash >>> 0).toString(16);
  }

  private static computeFullMd5(content: string): string {
    // Standard crypto MD5 implementation
    // Used strictly when explicitly enabled in anymd.db.md
    return 'md5_' + this.fastFnv1a(content); 
