### 💻 3. Core Engine Scaffolding (`anymd-core.ts`)

```typescript
/**
 * Anymd Core Engine - Zero Dependency Markdown Database
 */

export interface AnymdDoc {
  id: string;
  filename: string;
  body: string;
  frontmatter: Record<string, any>;
  tags: string[];
  links: string[];
  wordCount: number;
}

export class AnymdEngine {
  private docs: Map<string, AnymdDoc> = new Map();
  private sidecars: Map<string, any> = new Map();

  public ingest(rawText: string, filename: string): AnymdDoc {
    let frontmatter: Record<string, any> = {};
    let body = rawText;

    const fm = rawText.match(/^---\r?\n([\s\S]*?)\r?\n---\r?\n?/);
    if (fm) {
      body = rawText.slice(fm[0].length);
      fm[1].split(/\r?\n/).forEach(line => {
        const idx = line.indexOf(':');
        if (idx !== -1) {
          frontmatter[line.slice(0, idx).trim()] = line.slice(idx + 1).trim().replace(/^["']|["']$/g, '');
        }
      });
    }

    const tags = Array.from(new Set((rawText.match(/#[a-zA-Z0-9_\-\/]+/g) || []).map(t => t.toLowerCase())));
    const links = Array.from(new Set((rawText.match(/\[\[(.*?)\]\]/g) || []).map(l => l.slice(2, -2))));
    const id = filename.match(/^(\d{8,14})/)?.[1] || `${Date.now()}`;

    const doc: AnymdDoc = {
      id,
      filename,
      body: body.trim(),
      frontmatter,
      tags,
      links,
      wordCount: body.trim().split(/\s+/).filter(Boolean).length
    };

    this.docs.set(id, doc);
    return doc;
  }

  public query(tag?: string, search?: string): AnymdDoc[] {
    let results = Array.from(this.docs.values());
    if (tag) results = results.filter(d => d.tags.includes(tag.toLowerCase()));
    if (search) {
      const q = search.toLowerCase();
      results = results.filter(d => d.body.toLowerCase().includes(q) || d.filename.toLowerCase().includes(q));
    }
    return results;
  }
}

export const anymd = new AnymdEngine();
```

