public async openFile(filePath: string, forceMode?: ViewerMode): Promise<{ action: 'rendered_inline' | 'launched_external'; component?: string }> {
    const ext = filePath.split('.').pop()?.toLowerCase() || '';
    const config = this.handlers.get(ext) || { extension: ext, preferredMode: 'inline' };
    const activeMode = forceMode || config.preferredMode;

    // 1. In-Line Rendering Mode
    if (activeMode === 'inline') {
      const inlineComponent = this.resolveInlineViewerComponent(ext);
      return {
        action: 'rendered_inline',
        component: inlineComponent
      };
    }

    // 2. External Launch Mode (Node.js / Electron / Tauri OS bridge)
    if (activeMode === 'external') {
      await this.launchExternalApp(filePath, config.external_app);
      return { action: 'launched_external' };
    }

    return { action: 'rendered_inline' };
  }

  private resolveInlineViewerComponent(ext: string): string {
    switch (ext) {
      case 'pdf': return 'AnymdPdfViewer';
      case 'epub': return 'AnymdEpubReader';
      case 'csv': return 'AnymdTableSpreadsheet';
      case 'png':
      case 'jpg': return 'AnymdImageLightbox';
      case 'mp3': return 'AnymdAudioPlayer';
      default: return 'AnymdRawTextCode';
    }
